-- UI settings: pagination, animation and feature flags per page section

create table "public"."settings" (
  "id" bigint primary key generated by default as identity,
  "name" varchar,
  "type" "public"."Settings Types",
  "section" "public"."Page Section",
  "value" varchar,
  "is_active" boolean default true,
  "user" uuid,
  "data_type" "public"."Data Types",
  "namespace" varchar
);

alter table "public"."settings" add constraint "settings_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."settings" enable row level security;
create policy "Enable read access for all users" on "public"."settings" for select using (true);

grant all on "public"."settings" to postgres, anon, authenticated, service_role;
